const request = $json;
const validId = (value) => typeof value === 'string' && /^[A-Za-z0-9_-]{1,128}$/.test(value);
const request_id = validId(request.request_id) ? request.request_id : null;
const base = { request_id, execution_allowed: false, timestamp: new Date().toISOString() };
const deny = (code) => ({ json: { ...base, status: 'blocked', error: { code } } });

if (request.risk === 'restricted_finance') return deny('FINANCE_MODULE_REQUIRED');

if (!request_id || request.risk !== 'write_with_approval' || !validId(request.tool_id)) {
  return deny('INVALID_REVIEW_REQUEST');
}

if (request.operation !== 'preview') return deny('APPROVAL_BACKEND_UNCONFIGURED');

return {
  json: {
    ...base,
    status: 'review_required',
    review: { tool_id: request.tool_id, risk: 'write_with_approval' },
    approval_task: 'unconfigured',
  },
};
